#!/usr/bin/env python3
"""Select existing Lua/netbase packages and their closures from a reviewed lock."""
import argparse
import json
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument('--input', required=True, type=Path)
parser.add_argument('--output', required=True, type=Path)
args = parser.parse_args()
original = json.loads(args.input.read_text())
sets, selected = {}, set()
for architecture in ['amd64', 'arm64']:
    roots = {key.rsplit('=', 1)[0]: package['version']
             for key, package in original['packages'].items()
             if package['name'] in ['liblua5.1-0', 'netbase'] and ':' + architecture + '=' in key}
    assert len(roots) == 2, (architecture, roots)
    sets[architecture] = roots
    pending = [key + '=' + version for key, version in roots.items()]
    while pending:
        key = pending.pop()
        if key not in selected:
            selected.add(key)
            pending.extend(original['packages'][key]['depends_on'])
fixture = {
    '_generated': 'AUTO-GENERATED by select_lock_fixture.py; do not edit manually. Existing Debian archive metadata only; no DEBs are generated.',
    'version': 2,
    'sources': original['sources'],
    'packages': {key: original['packages'][key] for key in sorted(selected)},
    'dependency_sets': {name: {'sets': sets} for name in ['locked_import_ci', 'locked_import_ci_copy']},
}
args.output.write_text(json.dumps(fixture, sort_keys=True, indent=2) + '\n')
